insert into public.templates
  (id, name, domain, category, plain_description, structure_type, sections, fields, missing_detail_rules, fill_from_profile, recommendation_reason, related_document_ids, advice_boundary, brandable, flags, display_order)
values
  ('22222222-0000-4000-8000-000000000054', 'Forecasted Earnings', 'finance', 'Finance', 'A traceable earnings forecast built from confirmed historical figures and visible assumptions.', 'structured_form', '[{"key":"basis","name":"Basis and Assumptions","description":"Forecast period, baseline, scenarios and confirmed drivers.","is_required":true,"order":0},{"key":"forecast","name":"Revenue and Cost Forecast","description":"Formula-derived revenue and cost projections by period.","is_required":true,"order":1},{"key":"earnings","name":"Earnings and Scenarios","description":"Gross profit, EBITDA and net earnings where source data supports them.","is_required":true,"order":2},{"key":"risks","name":"Risks and Limitations","description":"Material sensitivities, unknowns and source limitations.","is_required":true,"order":3}]'::jsonb, '[{"name":"forecast_horizon","type":"text","label":"Forecast horizon","placeholder":"July 2026 to June 2027","required":true},{"name":"currency","type":"text","label":"Currency","placeholder":"AUD","required":true},{"name":"baseline_period","type":"text","label":"Historical baseline period","required":true}]'::jsonb, '[{"field":"forecast_horizon","reason":"Forecast values require a defined period and granularity.","is_required":true},{"field":"currency","reason":"Financial values cannot be interpreted without a currency.","is_required":true},{"field":"baseline_period","reason":"The source baseline distinguishes evidence from assumptions.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this when the user needs defensible future earnings projections rather than a historical P&L.', '["11111111-0000-4000-8000-000000000053"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","visualisations":["earnings trend","scenario comparison","sensitivity table"]}'::jsonb, 3),
  ('22222222-0000-4000-8000-000000000055', 'EBITDA Analysis', 'finance', 'Finance', 'A source-traceable EBITDA reconciliation with clearly labelled adjustments and limitations.', 'structured_form', '[{"key":"source_result","name":"Source Operating Result","description":"The confirmed starting result and accounting basis.","is_required":true,"order":0},{"key":"reconciliation","name":"EBITDA Reconciliation","description":"Interest, tax, depreciation and amortisation reconciliation.","is_required":true,"order":1},{"key":"adjustments","name":"Adjustments","description":"Each proposed normalising adjustment with evidence and rationale.","is_required":false,"order":2},{"key":"limitations","name":"Interpretation and Limitations","description":"Margins, comparisons and limits of the analysis.","is_required":true,"order":3}]'::jsonb, '[{"name":"reporting_period","type":"text","label":"Reporting period","required":true},{"name":"currency","type":"text","label":"Currency","placeholder":"AUD","required":true},{"name":"ebitda_definition","type":"textarea","label":"EBITDA definition and requested adjustments","required":true}]'::jsonb, '[{"field":"reporting_period","reason":"The calculation must be anchored to a reporting period.","is_required":true},{"field":"currency","reason":"The calculation requires a stated currency.","is_required":true},{"field":"ebitda_definition","reason":"Reported and adjusted EBITDA depend on the agreed definition.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to reconcile EBITDA from an uploaded P&L or trial balance without confusing it with cash flow or statutory profit.', '["11111111-0000-4000-8000-000000000053"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","visualisations":["EBITDA waterfall","margin trend","adjustment table"]}'::jsonb, 4),
  ('22222222-0000-4000-8000-000000000056', 'Investment Capital Gains Report', 'finance', 'Finance', 'A traceable review of investment disposals, cost bases and realised gains or losses.', 'structured_form', '[{"key":"coverage","name":"Source Coverage","description":"Owner, jurisdiction, period, supplied records and missing evidence.","is_required":true,"order":0},{"key":"transactions","name":"Holdings and Disposals","description":"Itemised acquisition and disposal records.","is_required":true,"order":1},{"key":"calculations","name":"Gain and Loss Calculations","description":"Traceable proceeds, cost base and gain or loss calculations.","is_required":true,"order":2},{"key":"summary","name":"Summary and Review Warning","description":"Bounded summary, assumptions and professional-review warning.","is_required":true,"order":3}]'::jsonb, '[{"name":"owner_entity","type":"text","label":"Owner or entity","required":true},{"name":"jurisdiction_tax_year","type":"text","label":"Jurisdiction and tax year","required":true},{"name":"parcel_method","type":"text","label":"Parcel-identification method","required":true}]'::jsonb, '[{"field":"owner_entity","reason":"Ownership determines which records belong in the report.","is_required":true},{"field":"jurisdiction_tax_year","reason":"Capital gains treatment depends on jurisdiction and period.","is_required":true},{"field":"parcel_method","reason":"A parcel method is required to pair acquisitions and disposals.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this for evidence-led investment gain and loss review, not as an invented tax return or liability calculation.', '[]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","visualisations":["realised gains by asset","proceeds versus cost base","holding periods"]}'::jsonb, 5),
  ('22222222-0000-4000-8000-000000000057', 'Quote / Estimate', 'business', 'Commercial', 'An itemised quote or estimate with confirmed pricing, scope, validity and acceptance terms.', 'structured_form', '[{"key":"parties","name":"Supplier and Customer","description":"Confirmed supplier, customer and quote identifiers.","is_required":true,"order":0},{"key":"pricing","name":"Scope and Itemised Pricing","description":"Scope, quantities, rates, tax and reconciled totals.","is_required":true,"order":1},{"key":"terms","name":"Terms and Acceptance","description":"Validity, exclusions, variations, payment and acceptance.","is_required":true,"order":2}]'::jsonb, '[{"name":"supplier","type":"text","label":"Supplier","required":true},{"name":"customer","type":"text","label":"Customer","required":true},{"name":"pricing_basis","type":"textarea","label":"Scope and itemised pricing","required":true}]'::jsonb, '[{"field":"supplier","reason":"The issuing supplier must be identified.","is_required":true},{"field":"customer","reason":"The intended customer must be identified.","is_required":true},{"field":"pricing_basis","reason":"A quote cannot be final without confirmed scope and prices.","is_required":true}]'::jsonb, '{"supplier":"business_name"}'::jsonb, 'Use this to present confirmed commercial scope and pricing for customer acceptance.', '["11111111-0000-4000-8000-000000000022"]'::jsonb, 'high-stakes', true, '{"deterministic_totals":true}'::jsonb, 20),
  ('22222222-0000-4000-8000-000000000058', 'Invoice', 'finance', 'Commercial', 'An itemised invoice with deterministic subtotal, tax and total calculations.', 'structured_form', '[{"key":"identity","name":"Invoice Details","description":"Supplier, customer, identifiers, issue date and due date.","is_required":true,"order":0},{"key":"items","name":"Supplied Items","description":"Confirmed items, quantities, unit prices and tax treatment.","is_required":true,"order":1},{"key":"payment","name":"Totals and Payment","description":"Reconciled totals, payment terms and confirmed payment details.","is_required":true,"order":2}]'::jsonb, '[{"name":"supplier","type":"text","label":"Supplier","required":true},{"name":"customer","type":"text","label":"Customer","required":true},{"name":"invoice_details","type":"textarea","label":"Invoice number, dates and itemised supplies","required":true}]'::jsonb, '[{"field":"supplier","reason":"The supplier must be identified.","is_required":true},{"field":"customer","reason":"The customer must be identified.","is_required":true},{"field":"invoice_details","reason":"An invoice requires confirmed identifiers, dates and supplied items.","is_required":true}]'::jsonb, '{"supplier":"business_name"}'::jsonb, 'Use this after goods or services have been supplied and payment is requested.', '["22222222-0000-4000-8000-000000000057"]'::jsonb, 'high-stakes', true, '{"deterministic_totals":true}'::jsonb, 6),
  ('22222222-0000-4000-8000-000000000059', 'Purchase Order', 'business', 'Commercial', 'A controlled purchase order recording requested items, agreed prices, delivery and approval.', 'structured_form', '[{"key":"order","name":"Order and Parties","description":"Buyer, supplier, PO number, approval and delivery details.","is_required":true,"order":0},{"key":"items","name":"Items and Totals","description":"Requested items, quantities, prices, tax and totals.","is_required":true,"order":1},{"key":"terms","name":"Terms and Revision","description":"Order terms and revision history without implying acceptance.","is_required":true,"order":2}]'::jsonb, '[{"name":"buyer","type":"text","label":"Buyer","required":true},{"name":"supplier","type":"text","label":"Supplier","required":true},{"name":"order_details","type":"textarea","label":"PO number, delivery and itemised order","required":true}]'::jsonb, '[{"field":"buyer","reason":"The purchasing entity must be identified.","is_required":true},{"field":"supplier","reason":"The intended supplier must be identified.","is_required":true},{"field":"order_details","reason":"The order requires confirmed identifiers, delivery and items.","is_required":true}]'::jsonb, '{"buyer":"business_name"}'::jsonb, 'Use this to authorise and record a purchase request without implying supplier acceptance.', '["22222222-0000-4000-8000-000000000057"]'::jsonb, 'high-stakes', true, '{"deterministic_totals":true}'::jsonb, 21),
  ('22222222-0000-4000-8000-000000000060', 'Cash Flow Forecast', 'finance', 'Finance', 'A period-by-period cash forecast showing confirmed assumptions, closing cash and low-cash risks.', 'structured_form', '[{"key":"basis","name":"Opening Cash and Assumptions","description":"Opening balance, horizon, granularity and scenario assumptions.","is_required":true,"order":0},{"key":"movements","name":"Inflows and Outflows","description":"Timed cash movements by confirmed category.","is_required":true,"order":1},{"key":"position","name":"Closing Cash and Scenarios","description":"Deterministic closing balances and low-cash periods.","is_required":true,"order":2}]'::jsonb, '[{"name":"opening_cash","type":"text","label":"Opening cash","required":true},{"name":"forecast_period","type":"text","label":"Forecast period and granularity","required":true},{"name":"cash_movements","type":"textarea","label":"Expected inflows and outflows with timing","required":true}]'::jsonb, '[{"field":"opening_cash","reason":"Closing cash cannot be calculated without opening cash.","is_required":true},{"field":"forecast_period","reason":"Cash timing requires a defined forecast period.","is_required":true},{"field":"cash_movements","reason":"The forecast requires confirmed inflow and outflow assumptions.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to assess future liquidity separately from accounting profit.', '["11111111-0000-4000-8000-000000000023"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","visualisations":["cash balance trend","inflows versus outflows","scenario comparison"]}'::jsonb, 7),
  ('22222222-0000-4000-8000-000000000061', 'Expense Claim / Reimbursement Report', 'finance', 'Finance', 'An evidenced, itemised expense claim with duplicate and approval controls.', 'structured_form', '[{"key":"claim","name":"Claim Details","description":"Claimant, organisation, project and claim period.","is_required":true,"order":0},{"key":"expenses","name":"Itemised Expenses","description":"Date, category, purpose, amount, currency, tax and receipt evidence.","is_required":true,"order":1},{"key":"approval","name":"Totals and Approval","description":"Reconciled totals, declaration and approval state.","is_required":true,"order":2}]'::jsonb, '[{"name":"claimant","type":"text","label":"Claimant","required":true},{"name":"claim_period","type":"text","label":"Claim period","required":true},{"name":"expense_items","type":"textarea","label":"Itemised expenses and receipt evidence","required":true}]'::jsonb, '[{"field":"claimant","reason":"The claimant must be identified.","is_required":true},{"field":"claim_period","reason":"The claim needs a defined period.","is_required":true},{"field":"expense_items","reason":"Reimbursement requires itemised confirmed expenses.","is_required":true}]'::jsonb, '{"claimant":"display_name"}'::jsonb, 'Use this to submit evidenced business expenses for review without deciding policy eligibility.', '[]'::jsonb, 'light', true, '{"supports_upload":true,"deterministic_totals":true}'::jsonb, 8),
  ('22222222-0000-4000-8000-000000000062', 'Project Plan', 'business', 'Project delivery', 'A practical project plan connecting objectives, deliverables, owners, milestones, risks and success measures.', 'structured_form', '[{"key":"foundation","name":"Objective, Governance and Scope","description":"Sponsor, objective, scope, constraints and success measures.","is_required":true,"order":0},{"key":"delivery","name":"Deliverables and Schedule","description":"Deliverables, tasks, owners, milestones and dependencies.","is_required":true,"order":1},{"key":"controls","name":"Risks and Communications","description":"Risks, controls, communications and review cadence.","is_required":true,"order":2}]'::jsonb, '[{"name":"project_objective","type":"textarea","label":"Project objective and scope","required":true},{"name":"deliverables","type":"textarea","label":"Deliverables and milestones","required":true},{"name":"owners","type":"textarea","label":"Owners and governance","required":true}]'::jsonb, '[{"field":"project_objective","reason":"The plan must have a confirmed objective and scope.","is_required":true},{"field":"deliverables","reason":"A project plan requires defined outputs and timing.","is_required":true},{"field":"owners","reason":"Accountability requires confirmed ownership.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to turn a confirmed project goal into governed delivery work.', '[]'::jsonb, 'none', true, '{}'::jsonb, 22),
  ('22222222-0000-4000-8000-000000000063', 'Project Status Report', 'business', 'Project delivery', 'A reporting-period update comparing confirmed progress with the approved project baseline.', 'structured_form', '[{"key":"status","name":"Executive Status","description":"Period, scope and evidence-based overall status.","is_required":true,"order":0},{"key":"progress","name":"Progress and Milestones","description":"Completed, upcoming and delayed work against plan.","is_required":true,"order":1},{"key":"attention","name":"Risks, Issues and Decisions","description":"Current risks, issues, decisions and support required.","is_required":true,"order":2}]'::jsonb, '[{"name":"reporting_period","type":"text","label":"Reporting period","required":true},{"name":"baseline_and_progress","type":"textarea","label":"Baseline and confirmed progress","required":true},{"name":"risks_issues","type":"textarea","label":"Risks, issues and decisions","required":true}]'::jsonb, '[{"field":"reporting_period","reason":"Status must be tied to a reporting period.","is_required":true},{"field":"baseline_and_progress","reason":"Progress cannot be assessed without baseline and actuals.","is_required":true},{"field":"risks_issues","reason":"Material risks and issues must be disclosed.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this for an evidence-backed project update without inventing progress or status.', '["22222222-0000-4000-8000-000000000062"]'::jsonb, 'none', true, '{}'::jsonb, 23),
  ('22222222-0000-4000-8000-000000000064', 'Meeting Agenda', 'business', 'Project delivery', 'A timed meeting agenda focused on preparation, decisions and accountable outcomes.', 'checklist', '[{"key":"details","name":"Meeting Details and Preparation","description":"Purpose, attendees, timing, access and pre-reading.","is_required":true,"order":0},{"key":"agenda","name":"Timed Agenda","description":"Ordered topics, presenters, timing and desired decisions.","is_required":true,"order":1},{"key":"outcomes","name":"Expected Outcomes","description":"Decisions, actions and link to later minutes.","is_required":true,"order":2}]'::jsonb, '[{"name":"meeting_purpose","type":"text","label":"Meeting purpose","required":true},{"name":"meeting_details","type":"text","label":"Participants, date and time","required":true},{"name":"agenda_items","type":"textarea","label":"Topics, presenters and timing","required":true}]'::jsonb, '[{"field":"meeting_purpose","reason":"The agenda must serve a clear purpose.","is_required":true},{"field":"meeting_details","reason":"Participants and timing are required for use.","is_required":true},{"field":"agenda_items","reason":"A meeting agenda requires ordered topics.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this before a meeting to focus preparation and decisions.', '["11111111-0000-4000-8000-000000000020"]'::jsonb, 'none', true, '{}'::jsonb, 24),
  ('22222222-0000-4000-8000-000000000065', 'Action Register', 'business', 'Project delivery', 'A controlled register of actions, owners, due dates, evidence and closure history.', 'structured_form', '[{"key":"register","name":"Action Register","description":"Action ID, source, wording, owner, due date, priority and status.","is_required":true,"order":0},{"key":"evidence","name":"Evidence and Closure","description":"Progress evidence, closure confirmation and revision history.","is_required":true,"order":1}]'::jsonb, '[{"name":"register_scope","type":"text","label":"Meeting or project source","required":true},{"name":"actions","type":"textarea","label":"Actions, owners, due dates and status","required":true}]'::jsonb, '[{"field":"register_scope","reason":"Actions need a source context.","is_required":true},{"field":"actions","reason":"The register requires confirmed action records.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to track accountable actions without marking work complete without evidence.', '["22222222-0000-4000-8000-000000000064"]'::jsonb, 'none', true, '{}'::jsonb, 25),
  ('22222222-0000-4000-8000-000000000066', 'Decision Log', 'business', 'Project delivery', 'A traceable record of decisions, options, confirmed rationale and review triggers.', 'structured_form', '[{"key":"decisions","name":"Decision Records","description":"ID, date, context, decision-maker, decision and status.","is_required":true,"order":0},{"key":"reasoning","name":"Options and Rationale","description":"Options considered, confirmed rationale and consequences.","is_required":true,"order":1}]'::jsonb, '[{"name":"decision_context","type":"text","label":"Project or meeting context","required":true},{"name":"decision_records","type":"textarea","label":"Decisions, makers, dates, options and rationale","required":true}]'::jsonb, '[{"field":"decision_context","reason":"Decisions need a defined context.","is_required":true},{"field":"decision_records","reason":"The log requires confirmed decision records.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to preserve why decisions were made without manufacturing rejected options or rationale.', '["22222222-0000-4000-8000-000000000064"]'::jsonb, 'none', true, '{}'::jsonb, 26),
  ('22222222-0000-4000-8000-000000000067', 'Handover Document', 'business', 'Project delivery', 'A practical transfer of responsibilities, active work, routines, risks, contacts and unresolved decisions.', 'structured_form', '[{"key":"scope","name":"Handover Scope and Ownership","description":"Outgoing owner, incoming owner, responsibilities and status.","is_required":true,"order":0},{"key":"operations","name":"Active Work and Routines","description":"Active work, deadlines, routines, systems and access routes.","is_required":true,"order":1},{"key":"risks","name":"Risks and Open Decisions","description":"Known risks, missing knowledge and unresolved decisions.","is_required":true,"order":2}]'::jsonb, '[{"name":"handover_owners","type":"text","label":"Outgoing and incoming owners","required":true},{"name":"handover_scope","type":"textarea","label":"Responsibilities, active work and routines","required":true},{"name":"open_items","type":"textarea","label":"Risks, deadlines and unresolved decisions","required":true}]'::jsonb, '[{"field":"handover_owners","reason":"The transfer parties must be clear.","is_required":true},{"field":"handover_scope","reason":"The responsibilities being transferred must be defined.","is_required":true},{"field":"open_items","reason":"Active risks and open decisions must not be hidden.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to transfer operational knowledge without storing passwords or secrets.', '[]'::jsonb, 'light', true, '{"forbid_secrets":true}'::jsonb, 27),
  ('22222222-0000-4000-8000-000000000068', 'Change Request', 'business', 'Project delivery', 'A controlled request describing a proposed change, its impacts, approval state and implementation plan.', 'structured_form', '[{"key":"request","name":"Request and Proposed Change","description":"Requester, baseline, change and reason.","is_required":true,"order":0},{"key":"impact","name":"Impact Assessment","description":"Cost, time, quality, risk and dependency impacts.","is_required":true,"order":1},{"key":"control","name":"Approval and Implementation","description":"Requested, approved and implemented states, rollout and rollback.","is_required":true,"order":2}]'::jsonb, '[{"name":"requester","type":"text","label":"Requester","required":true},{"name":"proposed_change","type":"textarea","label":"Baseline, proposed change and reason","required":true},{"name":"impact_assessment","type":"textarea","label":"Cost, time, quality and risk impacts","required":true}]'::jsonb, '[{"field":"requester","reason":"The request owner must be known.","is_required":true},{"field":"proposed_change","reason":"The baseline and proposed change must be explicit.","is_required":true},{"field":"impact_assessment","reason":"A change cannot be evaluated without its known impacts.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to assess and approve change without confusing requested, approved and implemented states.', '["22222222-0000-4000-8000-000000000062"]'::jsonb, 'none', true, '{}'::jsonb, 28),
  ('22222222-0000-4000-8000-000000000069', 'Leave Request and Availability Form', 'employment', 'Workforce', 'A privacy-conscious request recording leave dates or availability without implying approval.', 'structured_form', '[{"key":"request","name":"Employee Request","description":"Employee, workplace, request type, dates and status.","is_required":true,"order":0},{"key":"handover","name":"Evidence and Handover","description":"Minimum necessary reason, supplied evidence and handover.","is_required":false,"order":1},{"key":"approval","name":"Approval Route","description":"Approver, decision status and response record.","is_required":true,"order":2}]'::jsonb, '[{"name":"employee","type":"text","label":"Employee","required":true},{"name":"request_type_dates","type":"textarea","label":"Request type, dates or availability","required":true},{"name":"approval_route","type":"text","label":"Approval route","required":true}]'::jsonb, '[{"field":"employee","reason":"The requesting employee must be identified.","is_required":true},{"field":"request_type_dates","reason":"The requested leave or availability must be specific.","is_required":true},{"field":"approval_route","reason":"The form must show where the request goes.","is_required":true}]'::jsonb, '{"employee":"display_name"}'::jsonb, 'Use this to make a leave or availability request while keeping approval separate.', '[]'::jsonb, 'light', true, '{"sensitive_personal_data":true}'::jsonb, 17),
  ('22222222-0000-4000-8000-000000000070', 'Performance Improvement Plan', 'employment', 'Workforce', 'A neutral, evidence-based improvement plan with support, measures, review dates and response process.', 'structured_form', '[{"key":"expectations","name":"Expectations and Evidence","description":"Role expectations and specific confirmed performance evidence.","is_required":true,"order":0},{"key":"plan","name":"Required Improvement and Support","description":"Required change, measures, support and learning actions.","is_required":true,"order":1},{"key":"review","name":"Review and Response Process","description":"Review dates, supplied consequences and response process.","is_required":true,"order":2}]'::jsonb, '[{"name":"employee_role","type":"text","label":"Employee and role","required":true},{"name":"evidence_expectations","type":"textarea","label":"Expectations and specific evidence","required":true},{"name":"improvement_support","type":"textarea","label":"Required improvement, support and measures","required":true}]'::jsonb, '[{"field":"employee_role","reason":"The plan must relate to a defined role.","is_required":true},{"field":"evidence_expectations","reason":"A fair plan requires specific evidence and expectations.","is_required":true},{"field":"improvement_support","reason":"Required improvement and employer support must be explicit.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this for a procedurally fair improvement process without inventing misconduct or prior warnings.', '["11111111-0000-4000-8000-000000000019"]'::jsonb, 'high-stakes', true, '{"sensitive_personal_data":true}'::jsonb, 18),
  ('22222222-0000-4000-8000-000000000071', 'Training Plan and Skills Matrix', 'employment', 'Workforce', 'An evidence-based skills matrix and training plan that distinguishes not assessed from not competent.', 'structured_form', '[{"key":"requirements","name":"Roles and Required Competencies","description":"Roles, competencies and evidence standards.","is_required":true,"order":0},{"key":"matrix","name":"Current Capability and Gaps","description":"Evidence-backed current capability and gaps.","is_required":true,"order":1},{"key":"training","name":"Training and Reassessment Plan","description":"Actions, owners, dates and reassessment method.","is_required":true,"order":2}]'::jsonb, '[{"name":"roles_competencies","type":"textarea","label":"Roles and required competencies","required":true},{"name":"capability_evidence","type":"textarea","label":"Current evidence-backed capability","required":true},{"name":"training_actions","type":"textarea","label":"Training actions, owners and dates","required":true}]'::jsonb, '[{"field":"roles_competencies","reason":"The matrix requires defined competencies.","is_required":true},{"field":"capability_evidence","reason":"Capability status must be evidence based.","is_required":true},{"field":"training_actions","reason":"A training plan requires accountable actions.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to plan development without inferring qualifications or treating unassessed skills as failures.', '[]'::jsonb, 'light', true, '{}'::jsonb, 19),
  ('22222222-0000-4000-8000-000000000072', 'Incident / Near-Miss Report', 'business', 'Safety and operations', 'A factual incident record separating observations, immediate controls, analysis and corrective actions.', 'structured_form', '[{"key":"details","name":"Report Details","description":"Reporter, date, time, location and people involved.","is_required":true,"order":0},{"key":"facts","name":"Factual Sequence and Impact","description":"Observed sequence, injury, damage, witnesses and evidence.","is_required":true,"order":1},{"key":"response","name":"Controls, Notifications and Actions","description":"Immediate controls, notifications, analysis and corrective actions.","is_required":true,"order":2}]'::jsonb, '[{"name":"incident_details","type":"text","label":"Reporter, date, time and location","required":true},{"name":"factual_sequence","type":"textarea","label":"Factual sequence and known impact","required":true},{"name":"immediate_response","type":"textarea","label":"Immediate controls and notifications","required":true}]'::jsonb, '[{"field":"incident_details","reason":"The report needs accountable time and place details.","is_required":true},{"field":"factual_sequence","reason":"The event sequence must be recorded factually.","is_required":true},{"field":"immediate_response","reason":"Immediate controls and notifications are essential records.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to preserve incident facts and actions without deciding legal notification status.', '["11111111-0000-4000-8000-000000000039"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"sensitive_personal_data":true}'::jsonb, 29),
  ('22222222-0000-4000-8000-000000000073', 'Asset Register and Maintenance Log', 'business', 'Safety and operations', 'A traceable asset register with condition, service schedule and evidenced maintenance history.', 'structured_form', '[{"key":"assets","name":"Asset Register","description":"Asset identity, location, owner, serial, acquisition and warranty.","is_required":true,"order":0},{"key":"condition","name":"Condition and Criticality","description":"Confirmed condition, criticality and service requirements.","is_required":true,"order":1},{"key":"maintenance","name":"Maintenance History","description":"Evidenced completed work, cost and next due date.","is_required":true,"order":2}]'::jsonb, '[{"name":"asset_scope","type":"text","label":"Site or asset scope","required":true},{"name":"asset_records","type":"textarea","label":"Asset identities, locations and condition","required":true},{"name":"maintenance_records","type":"textarea","label":"Service schedule and evidenced maintenance","required":true}]'::jsonb, '[{"field":"asset_scope","reason":"The register needs a defined scope.","is_required":true},{"field":"asset_records","reason":"Assets must have confirmed identifiers and locations.","is_required":true},{"field":"maintenance_records","reason":"Maintenance status must trace to supplied records.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to track assets and service evidence without inventing maintenance completion or compliance.', '[]'::jsonb, 'light', true, '{"supports_upload":true,"export_format":"excel"}'::jsonb, 30),
  ('22222222-0000-4000-8000-000000000074', 'Stocktake / Inventory Count', 'business', 'Safety and operations', 'A controlled stock count preserving actual quantities, variances, recounts and approval.', 'structured_form', '[{"key":"control","name":"Count Controls","description":"Site, count date, counter and blind-count settings.","is_required":true,"order":0},{"key":"count","name":"Inventory Count","description":"Item, unit, expected quantity, actual quantity, variance and condition.","is_required":true,"order":1},{"key":"review","name":"Recount and Adjustment Review","description":"Recount history and adjustment approval.","is_required":true,"order":2}]'::jsonb, '[{"name":"count_details","type":"text","label":"Site, count date and counter","required":true},{"name":"inventory_rows","type":"textarea","label":"Items, units and actual quantities","required":true},{"name":"review_status","type":"textarea","label":"Variances, recounts and approval","required":true}]'::jsonb, '[{"field":"count_details","reason":"The count requires site, date and accountability.","is_required":true},{"field":"inventory_rows","reason":"Actual item counts are the core record.","is_required":true},{"field":"review_status","reason":"Variances and adjustments require review history.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to record stock counts without silently posting inventory adjustments.', '[]'::jsonb, 'none', true, '{"supports_upload":true,"export_format":"excel","deterministic_totals":true}'::jsonb, 31),
  ('22222222-0000-4000-8000-000000000075', 'Business Case', 'business', 'Strategy', 'A decision-ready business case comparing options, evidence, costs, benefits, risks and assumptions.', 'structured_form', '[{"key":"case","name":"Problem, Opportunity and Strategic Fit","description":"Decision context, need, objectives and stakeholders.","is_required":true,"order":0},{"key":"options","name":"Options and Evidence","description":"Options, quantified evidence, costs and benefits.","is_required":true,"order":1},{"key":"recommendation","name":"Risks and Recommendation","description":"Risks, assumptions, timeline, recommendation and decision.","is_required":true,"order":2}]'::jsonb, '[{"name":"decision_need","type":"textarea","label":"Problem or opportunity and decision required","required":true},{"name":"options_evidence","type":"textarea","label":"Options, costs, benefits and evidence","required":true},{"name":"risks_assumptions","type":"textarea","label":"Risks and assumptions","required":true}]'::jsonb, '[{"field":"decision_need","reason":"The case must define the decision.","is_required":true},{"field":"options_evidence","reason":"A business case must compare evidence-backed options.","is_required":true},{"field":"risks_assumptions","reason":"Material uncertainty must be visible.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this when a decision-maker needs an evidence-led recommendation and alternatives.', '["11111111-0000-4000-8000-000000000033"]'::jsonb, 'light', true, '{}'::jsonb, 32),
  ('22222222-0000-4000-8000-000000000076', 'Customer Feedback Summary', 'business', 'Customer insight', 'A bounded synthesis of supplied customer feedback, themes, evidence, severity and recommended actions.', 'structured_form', '[{"key":"method","name":"Source Coverage and Method","description":"Source set, period, audience, privacy limits and analysis method.","is_required":true,"order":0},{"key":"findings","name":"Themes and Evidence","description":"Themes, disclosed sentiment method, excerpts, frequency and severity.","is_required":true,"order":1},{"key":"actions","name":"Findings and Recommended Actions","description":"Bounded conclusions, limitations and prioritised actions.","is_required":true,"order":2}]'::jsonb, '[{"name":"feedback_scope","type":"text","label":"Source set and period","required":true},{"name":"analysis_goal","type":"text","label":"Audience and analysis goal","required":true},{"name":"feedback_sources","type":"textarea","label":"Customer feedback source material","required":true}]'::jsonb, '[{"field":"feedback_scope","reason":"Findings must be bounded to a source set and period.","is_required":true},{"field":"analysis_goal","reason":"The summary must serve a defined audience and purpose.","is_required":true},{"field":"feedback_sources","reason":"Themes cannot be generated without supplied feedback.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to turn supplied feedback into evidence-led themes without inventing respondents.', '[]'::jsonb, 'light', true, '{"supports_upload":true,"sensitive_personal_data":true}'::jsonb, 33),
  ('22222222-0000-4000-8000-000000000077', 'Competitor Comparison', 'business', 'Customer insight', 'A dated, cited comparison that distinguishes unknown information from absent features.', 'structured_form', '[{"key":"scope","name":"Decision Scope and Sources","description":"Decision purpose, competitors, date, criteria and permitted sources.","is_required":true,"order":0},{"key":"matrix","name":"Evidence Comparison","description":"Cited competitor evidence by criterion with unknowns explicit.","is_required":true,"order":1},{"key":"recommendation","name":"Interpretation and Recommendation","description":"Trade-offs, limitations and separate recommendation.","is_required":true,"order":2}]'::jsonb, '[{"name":"comparison_goal","type":"text","label":"Decision purpose and comparison date","required":true},{"name":"competitors_criteria","type":"textarea","label":"Competitors, criteria and weighting","required":true},{"name":"permitted_sources","type":"textarea","label":"Permitted or supplied sources","required":true}]'::jsonb, '[{"field":"comparison_goal","reason":"The comparison needs a defined decision and date.","is_required":true},{"field":"competitors_criteria","reason":"Competitors and criteria determine the analysis.","is_required":true},{"field":"permitted_sources","reason":"Claims require current permitted evidence.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this for a source-backed market comparison without treating unknown information as absent.', '[]'::jsonb, 'light', true, '{"requires_current_sources":true}'::jsonb, 34),
  ('22222222-0000-4000-8000-000000000078', 'Timesheet', 'employment', 'Workforce operations', 'An auditable record of actual hours, breaks, categories, approvals and corrections.', 'structured_form', '[{"key":"period","name":"Worker and Pay Period","description":"Business, worker, engagement, project, pay period and timezone.","is_required":true,"order":0},{"key":"entries","name":"Actual Time Entries","description":"Dates, actual starts and ends, breaks and confirmed hour categories.","is_required":true,"order":1},{"key":"totals","name":"Totals, Approval and Corrections","description":"Deterministic totals, submission, approval and revision history.","is_required":true,"order":2}]'::jsonb, '[{"name":"worker_period","type":"text","label":"Business, worker, pay period and timezone","required":true},{"name":"time_entries","type":"textarea","label":"Actual dated time and break entries","required":true},{"name":"approval_process","type":"text","label":"Submission and approval process","required":true}]'::jsonb, '[{"field":"worker_period","reason":"Actual hours require a worker, period and timezone.","is_required":true},{"field":"time_entries","reason":"A timesheet requires actual time records.","is_required":true},{"field":"approval_process","reason":"The record needs a submission and approval route.","is_required":true}]'::jsonb, '{"worker_period":"display_name"}'::jsonb, 'Use this to record actual time, not a planned roster or unsupported wage entitlement.', '["22222222-0000-4000-8000-000000000079"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","deterministic_totals":true,"append_only_history":true}'::jsonb, 20),
  ('22222222-0000-4000-8000-000000000079', 'Staff Roster', 'employment', 'Workforce operations', 'A forward-looking staff schedule with availability, coverage, conflicts and publication history.', 'structured_form', '[{"key":"basis","name":"Roster Basis and Constraints","description":"Site, period, timezone, operating hours, roles and confirmed constraints.","is_required":true,"order":0},{"key":"schedule","name":"Scheduled Shifts","description":"Employees or placeholders, roles, dates, locations, shifts and breaks.","is_required":true,"order":1},{"key":"checks","name":"Coverage and Change Control","description":"Coverage, conflicts, publication state and amendment history.","is_required":true,"order":2}]'::jsonb, '[{"name":"roster_basis","type":"text","label":"Business, site, roster period and timezone","required":true},{"name":"staff_constraints","type":"textarea","label":"Staff, roles, availability and coverage requirements","required":true},{"name":"scheduled_shifts","type":"textarea","label":"Dated shifts, roles, locations and breaks","required":true}]'::jsonb, '[{"field":"roster_basis","reason":"A roster requires a site, period and timezone.","is_required":true},{"field":"staff_constraints","reason":"Coverage cannot be planned without roles and availability.","is_required":true},{"field":"scheduled_shifts","reason":"The roster requires explicit planned shifts.","is_required":true}]'::jsonb, '{}'::jsonb, 'Use this to plan future work while keeping availability, qualifications and approval facts explicit.', '["22222222-0000-4000-8000-000000000078"]'::jsonb, 'high-stakes', true, '{"supports_upload":true,"export_format":"excel","append_only_history":true,"calendar_export":true}'::jsonb, 21)
